ALTER TABLE users DROP CONSTRAINT users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN ('admin','courier','client','preparation','plant_admin','custom','client_member'));
ALTER TABLE users ADD COLUMN permissions jsonb NOT NULL DEFAULT '[]';
ALTER TABLE users ADD COLUMN client_account_id uuid REFERENCES users;
ALTER TABLE users ADD COLUMN can_view_portfolio boolean NOT NULL DEFAULT false;
UPDATE users SET role='custom',permissions='["orders","plant"]' WHERE role='plant_admin';
ALTER TABLE branches DROP CONSTRAINT branches_city_check;
ALTER TABLE branches ADD CONSTRAINT branches_city_check CHECK(length(trim(city)) BETWEEN 1 AND 100);
ALTER TABLE orders ADD COLUMN payment_method text NOT NULL DEFAULT 'cash' CHECK(payment_method IN ('cash','online','credit'));
ALTER TABLE orders ADD COLUMN operation_day date;
UPDATE orders SET operation_day=(window_start AT TIME ZONE 'America/Bogota')::date;
ALTER TABLE business_days ADD COLUMN intake_closed_at timestamptz;
ALTER TABLE business_days ADD COLUMN close_requested_at timestamptz;
ALTER TABLE settlements ADD COLUMN submitted_at timestamptz;
ALTER TABLE settlements ADD COLUMN status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('submitted','confirmed'));
ALTER TABLE audit ADD COLUMN entity_type text NOT NULL DEFAULT 'order';
ALTER TABLE audit ADD COLUMN entity_id text;
ALTER TABLE audit ADD COLUMN details jsonb NOT NULL DEFAULT '{}';
CREATE INDEX audit_time_idx ON audit(created_at DESC,id DESC);
CREATE INDEX audit_actor_idx ON audit(actor_id,created_at DESC);
CREATE INDEX business_days_closed_idx ON business_days(day DESC);
CREATE INDEX orders_courier_idx ON orders(courier_id,operation_day);
CREATE TABLE catalog_products(id uuid PRIMARY KEY,name text NOT NULL,active boolean NOT NULL DEFAULT true);
ALTER TABLE products ADD COLUMN catalog_product_id uuid REFERENCES catalog_products;
INSERT INTO catalog_products(id,name) SELECT DISTINCT md5('group:'||CASE WHEN image_key IN ('entera','trozos','picada','rayada') THEN 'Piña' ELSE name END)::uuid,CASE WHEN image_key IN ('entera','trozos','picada','rayada') THEN 'Piña' ELSE name END FROM products;
UPDATE products SET catalog_product_id=md5('group:'||CASE WHEN image_key IN ('entera','trozos','picada','rayada') THEN 'Piña' ELSE name END)::uuid;
UPDATE products SET presentation=CASE WHEN image_key IN ('entera','trozos','picada','rayada') THEN name ELSE 'Estándar' END WHERE presentation IN ('Por kilogramo','Por libra (500 g)','Arroba colombiana (25 libras / 12,5 kg)');
CREATE INDEX products_group_idx ON products(catalog_product_id);
CREATE TABLE order_schedules(id uuid PRIMARY KEY,client_id uuid NOT NULL REFERENCES users,created_by uuid NOT NULL REFERENCES users,source_order_id uuid REFERENCES orders,body jsonb NOT NULL,frequency text NOT NULL CHECK(frequency IN ('days','weekly')),interval_days int NOT NULL CHECK(interval_days BETWEEN 1 AND 365),weekdays int[] NOT NULL DEFAULT '{}',next_day date NOT NULL,end_day date,active boolean NOT NULL DEFAULT true,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE schedule_runs(schedule_id uuid REFERENCES order_schedules,day date,status text NOT NULL,order_id uuid REFERENCES orders,error text,PRIMARY KEY(schedule_id,day));
CREATE INDEX schedules_due_idx ON order_schedules(next_day) WHERE active;
ALTER TABLE schedule_runs ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
